4. Clinical Analogy Tasks

analogy &lt;- function(word_vectors, a, b, c, topn = 3) {
  vec &lt;- word_vectors[a, ] - word_vectors[b, ] + word_vectors[c, ]
  sims &lt;- apply(word_vectors, 1, cosine_sim, b = vec)
  sims &lt;- sims[!names(sims) %in% c(a, b, c)]
  head(sort(sims, decreasing = TRUE), topn)
}

