4. Regex Fallback NER

regex_ner &lt;- function(text, entity_lists) {
  entities &lt;- purrr::imap_dfr(entity_lists, function(patterns, label) {
    purrr::map_dfr(patterns, function(pattern) {
      regex &lt;- paste0("\\b", stringr::str_replace_all(pattern, "([\\W])", "\\\\\\1"), "\\b")
      m &lt;- gregexpr(regex, text, perl = TRUE, ignore.case = TRUE)[[1]]
      if (m[1] == -1) {
        return(tibble::tibble(text = character(), label = character(),
                              start = integer(), end = integer()))
      }
      tibble::tibble(
        text  = regmatches(text, list(m))[[1]],
        label = label,
        start = as.integer(m),
        end   = as.integer(m + attr(m, "match.length"))
      )
    })
  })
  if (nrow(entities) == 0) return(entities)
  entities &lt;- dplyr::arrange(entities, start, dplyr::desc(end - start))
  filtered &lt;- list(); prev_end &lt;- -1L
  for (k in seq_len(nrow(entities))) {
    if (entities$start[k] &gt;= prev_end) {
      filtered[[length(filtered) + 1]] &lt;- entities[k, ]
      prev_end &lt;- entities$end[k]
    }
  }
  dplyr::bind_rows(filtered)
}

