5. Section Extraction

section_patterns &lt;- c(
  HPI         = "(?:HISTORY OF PRESENT ILLNESS|HPI)\\s*:?",
  MEDICATIONS = "MEDICATIONS?\\s*:?",
  ASSESSMENT  = "(?:ASSESSMENT(?:\\s+AND\\s+PLAN)?|A/?P|IMPRESSION)\\s*:?",
  LABS        = "LABS?\\s*:?",
  PLAN        = "PLAN\\s*:?",
  DISCHARGE   = "DISCHARGE CONDITION\\s*:?"
)

extract_sections &lt;- function(text) {
  headers &lt;- purrr::imap_dfr(section_patterns, function(pattern, name) {
    m &lt;- gregexpr(pattern, text, perl = TRUE, ignore.case = TRUE)[[1]]
    if (m[1] == -1) {
      return(tibble::tibble(start = integer(), end = integer(), name = character()))
    }
    tibble::tibble(
      start = as.integer(m),
      end   = as.integer(m + attr(m, "match.length")),
      name  = name
    )
  })
  if (nrow(headers) == 0) return(list())
  headers &lt;- dplyr::arrange(headers, start)
  sections &lt;- list()
  for (i in seq_len(nrow(headers))) {
    next_start &lt;- if (i &lt; nrow(headers)) headers$start[i + 1] else nchar(text) + 1
    content &lt;- substr(text, headers$end[i], next_start - 1)
    content &lt;- stringr::str_squish(stringr::str_replace_all(content, "\\n+", " "))
    if (nzchar(content)) sections[[headers$name[i]]] &lt;- content
  }
  sections
}

