make_dfm &lt;- function(texts, type = c("bow", "tfidf_uni", "tfidf_bi", "char"),
                     train_dfm = NULL) {
  type &lt;- match.arg(type)
  texts &lt;- as.character(texts)
  names(texts) &lt;- paste0("doc", seq_along(texts))
  if (type == "char") {
    toks &lt;- quanteda::tokens(texts, what = "character") |&gt;
      quanteda::tokens_ngrams(n = 3:5, concatenator = "")
  } else {
    ngram &lt;- if (type == "tfidf_bi") 1:2 else 1L
    toks &lt;- quanteda::tokens(texts, remove_punct = TRUE) |&gt;
      quanteda::tokens_remove(clinical_stop_words) |&gt;
      quanteda::tokens_ngrams(n = ngram)
  }
  d &lt;- quanteda::dfm(toks)
  if (!is.null(train_dfm)) {
    d &lt;- quanteda::dfm_match(d, features = quanteda::featnames(train_dfm))
  }
  max_feat &lt;- if (type %in% c("tfidf_bi", "char")) 5000L else 3000L
  if (is.null(train_dfm) && nfeat(d) &gt; max_feat) {
    keep &lt;- names(quanteda::topfeatures(d, n = max_feat))
    d &lt;- quanteda::dfm_select(d, pattern = keep)
  }
  if (type != "bow") d &lt;- quanteda::dfm_tfidf(d)
  d
}

