  xtr &lt;- as.matrix(quanteda::convert(dtr, to = "matrix"))
  xte &lt;- as.matrix(quanteda::convert(dte, to = "matrix"))
  if (is.null(colnames(xtr))) colnames(xtr) &lt;- paste0("f", seq_len(ncol(xtr)))
  if (is.null(colnames(xte))) colnames(xte) &lt;- colnames(xtr)
  xtr[!is.finite(xtr)] &lt;- 0
  xte[!is.finite(xte)] &lt;- 0
  ytr &lt;- tr[[y_col]]
  yte &lt;- te[[y_col]]
  if (y_col == "condition") {
    ytr_f &lt;- factor(ytr)
    yte_f &lt;- factor(yte, levels = levels(ytr_f))
    levs &lt;- levels(ytr_f)
    cents &lt;- t(vapply(levs, function(lv) {
      rows &lt;- xtr[ytr_f == lv, , drop = FALSE]
      if (!nrow(rows)) rep(0, ncol(xtr)) else colMeans(rows)
    }, numeric(ncol(xtr))))
    pred &lt;- apply(xte, 1, function(v) {
      d &lt;- sqrt(rowSums(sweep(cents, 2, v, "-")^2))
      levs[which.min(d)]
    })
    yardstick::f_meas_vec(yte_f, factor(pred, levels = levels(ytr_f)),
                          estimator = "macro_weighted")
  } else {
    ytr_n &lt;- as.numeric(ytr)
    fit &lt;- glmnet::glmnet(xtr, ytr_n, family = "binomial",
                          lambda = 0.01, maxit = 1000)
    proba &lt;- as.numeric(predict(fit, newx = xte, type = "response"))
    yardstick::roc_auc_vec(factor(yte, levels = c(0, 1)), proba, event_level = "second")
  }
}

