2. TextRank Extractive Summarisation
Sentence scoring with tidytext / quanteda TF-IDF and a PageRank-style iteration (TextRank analogue). lexRankr implements the same algorithm if you prefer a package wrapper.

stops &lt;- c(quanteda::stopwords("en"),
           "patient", "mg", "daily", "was", "were", "the", "a", "an",
           "admission", "discharge", "history", "hospital", "noted")

split_sentences &lt;- function(text) {
  sents &lt;- unlist(quanteda::tokens(text, what = "sentence"))
  sents &lt;- stringr::str_squish(sents)
  n_words &lt;- vapply(strsplit(sents, "\\s+"), length, integer(1))
  sents[n_words &gt; 5]
}

sentence_tfidf &lt;- function(sents) {
  toks &lt;- quanteda::tokens(sents, remove_punct = TRUE) |&gt;
    quanteda::tokens_tolower() |&gt;
    quanteda::tokens_remove(stops)
  quanteda::dfm_tfidf(quanteda::dfm(toks))
}

cosine_sim_mat &lt;- function(mat) {
  nrms &lt;- sqrt(rowSums(mat^2)); nrms[nrms == 0] &lt;- 1
  Xn &lt;- mat / nrms
  sim &lt;- tcrossprod(Xn)
  diag(sim) &lt;- 0
  sim
}

textrank_summarise &lt;- function(text, n_sents = 5) {
  sents &lt;- split_sentences(text)
  if (length(sents) &lt;= n_sents) {
    return(list(sents = sents, scores = rep(1, length(sents))))
  }
  d &lt;- sentence_tfidf(sents)
  mat &lt;- as.matrix(d)
  if (nrow(mat) == 0 || ncol(mat) == 0) {
    return(list(sents = sents[seq_len(n_sents)], scores = rep(1, n_sents)))
  }
  sim &lt;- cosine_sim_mat(mat)
  n &lt;- nrow(sim)
  scores &lt;- rep(1 / n, n)
  for (iter in seq_len(50)) {
    rs &lt;- rowSums(sim); rs[rs == 0] &lt;- 1
    trans &lt;- t(sim / rs)
    scores &lt;- 0.15 / n + 0.85 * as.numeric(trans %*% scores)
  }
  top_idx &lt;- sort(order(scores, decreasing = TRUE)[seq_len(n_sents)])
  list(sents = sents[top_idx], scores = scores)
}

