get_ngrams &lt;- function(text, n) {
  toks &lt;- stringr::str_extract_all(tolower(text), "\\b\\w+\\b")[[1]]
  if (length(toks) &lt; n) return(character())
  vapply(seq_len(length(toks) - n + 1), function(i) {
    paste(toks[i:(i + n - 1)], collapse = " ")
  }, character(1))
}

rouge_n &lt;- function(hyp, ref, n = 1) {
  h &lt;- get_ngrams(hyp, n)
  r &lt;- get_ngrams(ref, n)
  if (length(r) == 0) return(list(p = 0, r = 0, f1 = 0))
  hc &lt;- table(h); rc &lt;- table(r)
  ov &lt;- sum(purrr::map_dbl(names(rc), function(ng) {
    min(if (ng %in% names(hc)) as.numeric(hc[[ng]]) else 0, as.numeric(rc[[ng]]))
  }))
  p  &lt;- if (length(h) &gt; 0) ov / length(h) else 0
  re &lt;- ov / length(r)
  f1 &lt;- if ((p + re) &gt; 0) 2 * p * re / (p + re) else 0
  list(p = round(p, 4), r = round(re, 4), f1 = round(f1, 4))
}

rouge_l &lt;- function(hyp, ref) {
  h &lt;- stringr::str_extract_all(tolower(hyp), "\\b\\w+\\b")[[1]]
  r &lt;- stringr::str_extract_all(tolower(ref), "\\b\\w+\\b")[[1]]
  m &lt;- length(h); n &lt;- length(r)
  dp &lt;- matrix(0, m + 1, n + 1)
  if (m &gt; 0 && n &gt; 0) {
    for (i in seq_len(m)) {
      for (j in seq_len(n)) {
        dp[i + 1, j + 1] &lt;- if (h[i] == r[j]) dp[i, j] + 1 else max(dp[i, j + 1], dp[i + 1, j])
      }
    }
  }
  lcs &lt;- dp[m + 1, n + 1]
  p  &lt;- if (m &gt; 0) lcs / m else 0
  re &lt;- if (n &gt; 0) lcs / n else 0
  f1 &lt;- if ((p + re) &gt; 0) 2 * p * re / (p + re) else 0
  list(p = round(p, 4), r = round(re, 4), f1 = round(f1, 4))
}

