log_file &lt;- fs::path(PROJECT_ROOT, "pipeline.log")
logger_write &lt;- function(level, message) {
  line &lt;- sprintf("%s | %-7s | %s", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), level, message)
  cat(line, "\n")
  cat(line, "\n", file = log_file, append = TRUE)
