log_step &lt;- function(name, fn) {
  force(name); force(fn)
  function(...) {
    logger_write("INFO", paste("START ", name))
    t0 &lt;- proc.time()[["elapsed"]]
    tryCatch({
      result &lt;- fn(...)
      elapsed &lt;- proc.time()[["elapsed"]] - t0
      logger_write("INFO", sprintf("OK     %s | %.2fs", name, elapsed))
      result
    }, error = function(e) {
      logger_write("ERROR", sprintf("FAIL   %s | %s", name, e$message))
      stop(e)
    })
  }
}

