reproducibility_audit &lt;- function(project_dir) {
  root &lt;- fs::path(project_dir)
  issues &lt;- character()
  score &lt;- 100

  req &lt;- fs::path(root, "packages.R")
  lock &lt;- fs::path(root, "renv.lock")
  if (!fs::file_exists(req) && !fs::file_exists(lock)) {
    issues &lt;- c(issues, "MISSING packages.R / renv.lock")
    score &lt;- score - 20
  } else if (fs::file_exists(req)) {
    lines &lt;- readLines(req)
    pkg_lines &lt;- lines[grepl("=", lines) & !grepl("^\\s*#", lines) & grepl("dplyr|ggplot2|xgboost", lines)]
    unpinned &lt;- pkg_lines[!grepl("&gt;=|==|&lt;=", pkg_lines)]
    if (length(unpinned)) {
      issues &lt;- c(issues, paste("Unpinned packages:", paste(unpinned, collapse = ", ")))
      score &lt;- score - 10
    }
  }

  if (!fs::file_exists(fs::path(root, "data", "MANIFEST.json"))) {
    issues &lt;- c(issues, "MISSING data/MANIFEST.json")
    score &lt;- score - 20
  }

  gi &lt;- fs::path(root, ".gitignore")
  if (fs::file_exists(gi)) {
    content &lt;- paste(readLines(gi), collapse = "\n")
    for (p in c(".Renviron", "data/raw/")) {
      if (!grepl(p, content, fixed = TRUE)) {
        issues &lt;- c(issues, paste(".gitignore missing:", p))
        score &lt;- score - 5
      }
    }
  } else {
    issues &lt;- c(issues, "MISSING .gitignore")
    score &lt;- score - 15
  }

  if (!fs::file_exists(fs::path(root, "pipeline.log"))) {
    issues &lt;- c(issues, "No pipeline.log found")
    score &lt;- score - 5
  }

  list(score = max(0, score), issues = issues)
}

